-static int get_fwd_blk_id(void)
-{
-	int blk_id = -1;
-	u32  int_mask = shell_task_enter_critical();
-	for (int i = 0; i < 3; i++) {
-		if (s_fwd_status & (1 << i)) {
-			int mask = ~(1 << i);
-			s_fwd_status &= mask;
-			blk_id = i;
-			break;
-		}
-	}
-	shell_task_exit_critical(int_mask);
-	return blk_id;
-}
